+import React from "react";
+
+import { ContextMenuButton, useContextMenu } from "../../structures/ContextMenu";
+import UIStore from "../../../stores/UIStore";
+import IconizedContextMenu, { IconizedContextMenuOptionList } from "./IconizedContextMenu";
+
+interface Props extends Omit<React.ComponentProps<typeof ContextMenuButton>, "isExpanded" | "onClick" | "label"> {
+    options: React.ReactNode[];
+    title: string;
+}
+
+export const KebabContextMenu: React.FC<Props> = ({ options, title, disabled, ...props }) => {
+    const [isOpen, button, openMenu, closeMenu] = useContextMenu<HTMLDivElement>();
+    const onOpen = (ev: React.MouseEvent | React.KeyboardEvent | React.FormEvent): void => {
+        if (disabled) return;
+        button.current?.focus();
+        openMenu(ev);
+    };
+    const rect = isOpen && button.current?.getBoundingClientRect();
+
+    return <>
+        <ContextMenuButton
+            {...props}
+            inputRef={button}
+            label={title}
+            isExpanded={isOpen}
+            disabled={disabled}
+            aria-disabled={disabled}
+            onClick={onOpen}
+            className="mx_KebabContextMenu_button"
+        >
+            <span className="mx_KebabContextMenu_icon" aria-hidden="true" />
+        </ContextMenuButton>
+        { rect && <IconizedContextMenu
+            onFinished={closeMenu}
+            closeOnInteraction
+            rightAligned
+            top={rect.bottom + window.scrollY}
+            right={UIStore.instance.windowWidth - rect.right - window.scrollX}
+            className="mx_KebabContextMenu_menu"
+        >
+            <IconizedContextMenuOptionList first red>
+                { options }
+            </IconizedContextMenuOptionList>
+        </IconizedContextMenu> }
+    </>;
+};
